with filtered_orders as (select * from orders where customer_id in (2, 13) or customer_id is null), agg as (select case when amount >= 1570 then 'high' when amount >= 700 then 'mid' else 'low' end as amount_bucket, min(order_date) as first_order_date, count(case when channel = 'store' then 1 end) as store_count from filtered_orders group by case when amount >= 1570 then 'high' when amount >= 700 then 'mid' else 'low' end) select * from agg order by store_count, amount_bucket limit 1;
